AutoFactory factory = new AutoFactory(
    robotState::getPose, robotState::resetPose,
    drive::followSample,          // Consumer<SwerveSample> or Consumer<DifferentialSample>
    true,                         // useAllianceFlipping
    drive,
    (traj, starting) -> Logger.recordOutput("Auto/Traj", traj.getPoses())); // TrajectoryLogger
factory.bind("intake", superstructure.request(INTAKE));   // global event marker
AutoRoutine r = factory.newRoutine("3pc");
AutoTrajectory t1 = r.trajectory("startToScore");
AutoTrajectory t2 = r.trajectory("scoreToSweep", 1);      // split index
r.active().onTrue(Commands.sequence(t1.resetOdometry(), t1.cmd()));
t1.atTimeBeforeEnd(0.3).onTrue(superstructure.request(SCORE_READY));
t1.done().and(sensors::hasPiece).onTrue(t2.cmd());
t1.done().and(() -> !sensors.hasPiece()).onTrue(retry.cmd());

