PathPlannerLogging.setLogActivePathCallback(poses -> Logger.recordOutput("Auto/ActivePath", poses.toArray(Pose2d[]::new)));
PathPlannerLogging.setLogTargetPoseCallback(p -> Logger.recordOutput("Auto/TargetPose", p));
// Choreo equivalent is the TrajectoryLogger passed to the AutoFactory constructor.

DriveTrainSimulationConfig cfg = DriveTrainSimulationConfig.Default()
    .withRobotMass(Kilograms.of(cfgMassKg))
    .withGyro(COTS.ofPigeon2())
    .withSwerveModule(COTS.ofMark4(DCMotor.getKrakenX60(1), DCMotor.getKrakenX60(1), COTS.WHEELS.COLSONS.cof, 3));
// PumpkinLib wraps this as PumpkinSim.field() and drives the same auto Command headlessly.

private final SwerveRequest.ApplyRobotSpeeds applyRobotSpeeds = new SwerveRequest.ApplyRobotSpeeds();
drive.setControl(applyRobotSpeeds.withSpeeds(ChassisSpeeds.discretize(speeds, 0.02))
    .withWheelForceFeedforwardsX(ff.robotRelativeForcesXNewtons())
    .withWheelForceFeedforwardsY(ff.robotRelativeForcesYNewtons()));

