public interface PumpkinTrajectory {
  Command cmd();                 // follow it
  Command resetOdometry();       // seed pose from start sample
  Trigger active();
  Trigger inactive();
  Trigger done();
  Trigger doneFor(double s);
  Trigger atTime(double t);
  Trigger atTimeBeforeEnd(double t);   // "start intake 0.3s before arrival"
  Trigger atEvent(String name);
  Trigger beforeEvent(String name, double s);
  Trigger atTranslation(Translation2d t, double tolM);
  Trigger atPose(Pose2d p, double tolM, double tolRad);
  Optional<Pose2d> initialPose();
  Optional<Pose2d> finalPose();
  double totalTimeSeconds();
  PumpkinTrajectory mirrored();  // alliance handling, one call
}
// Two implementations, chosen by source:
PumpkinTrajectory t = auto.choreo("startToScore");        // ChoreoLib AutoTrajectory delegate
PumpkinTrajectory t = auto.pathplanner("Score Path");     // PathPlannerAuto + PathPlannerPath delegate
PumpkinTrajectory t = auto.pathfindTo(Poses.REEF_A, PumpkinConstraints.FAST); // PP pathfinding only
// Backing: Choreo side wraps choreo.auto.AutoTrajectory 1:1 (atTimeBeforeEnd/doneFor/atPose exist natively).
// PathPlanner side: atTimeBeforeEnd == PathPlannerAuto.timeElapsed(totalTime - t) computed from
//   path.getIdealTrajectory(robotConfig).get().getTotalTimeSeconds(); beforeEvent maps to
//   PathPlannerAuto.beforeEvent(name, s); atTranslation maps to nearFieldPosition(t, tol).

public enum State { STOW, INTAKE, L1, L2, L3, L4, CLIMB }
PumpkinSuperstructure<State> ss = PumpkinSuperstructure.of(State.class)
  .subsystems(elevator, arm, wrist)          // owns requirements exactly once
  .state(STOW,  g -> g.elevator(0.0).arm(Degrees.of(90)))
  .state(L4,    g -> g.elevator(1.42).arm(Degrees.of(35)))
  .edge(STOW, L4, /*cost*/1.0, /*guard*/() -> true)
  .edge(L4, CLIMB, 2.0, () -> !hasPiece())   // illegal shortcuts simply omitted
  .illegalIf(() -> elevator.height() < 0.3 && arm.angle() < Degrees.of(20)) // collision envelope
  .build();
// Auto/teleop usage — never blocks, never fights the drive command:
Command c = ss.request(L4);        // Command that finishes when at goal
Trigger  t = ss.atState(L4);
ss.requestAsync(L4);               // fire-and-forget from a trajectory trigger
// Internally: AStarSolver<State>.solve(current, goal, heuristic, neighbors) -> List<State>,
// executed as a sequence of setpoint transitions; a new request re-plans from the current node.

PumpkinAutoSelector sel = new PumpkinAutoSelector("Auto");
sel.addRoutine("Midline Sweep",
    List.of(Question.of("Start", LEFT, CENTER, RIGHT),
            Question.of("First piece", M1, M2, M3),
            Question.of("Bail out?", YES, NO)),
    responses -> autos.midlineSweep(responses));   // Function<Responses, Command>, lazy
sel.addRoutine("Do Nothing", List.of(), r -> Commands.none());
sel.setDefault("Do Nothing");
RobotModeTriggers.autonomous().whileTrue(sel.selectedCommandScheduler());
// Responses frozen on first autonomous enable (6328 behavior).
// Publishes NT topics Auto/Question1..N + Auto/Selected and logs the resolved variant name
// so log replay identifies exactly which auto ran.
// Optional: sel.importPathPlannerAutos()  -> wraps AutoBuilder.getAllAutoNames()
//           sel.importChoreoRoutines(factory)

@Test void allAutosFitBudget() {
  PumpkinAutoTest.forEach(selector.allVariants(), variant -> {
    var result = PumpkinAutoTest.simulate(variant)
        .withField(PumpkinSim.field(2026))
        .withDriveConfig(driveSimConfig)
        .withOdometryNoise(0.02, Degrees.of(0.5))   // stress odometry drift
        .run();
    assertThat(result.elapsed()).isLessThan(Seconds.of(15.0));
    assertThat(result.stepOverruns()).isEmpty();
    assertThat(result.finalPose()).isWithin(Meters.of(0.15)).of(variant.expectedEndPose());
    assertThat(result.scoredPieces()).isAtLeast(3);
    result.writeWpilog("build/autotest/" + variant.name() + ".wpilog"); // open in AdvantageScope
  });
}
// Plus a Gradle task: ./gradlew pumpkinAutoReport -> HTML matrix of variant x {time, score, drift}

PumpkinNav.configure(cfg -> cfg
    .replaySafe(true)              // installs LocalADStarAK when AdvantageKit is on the classpath
    .warmupOnInit(true)            // FollowPathCommand.warmupCommand() + PathfindingCommand warmup
                                   // + AutoFactory.warmupCmd() if ChoreoLib present
    .navgrid("auto",   "auto_navgrid.json")
    .navgrid("teleop", "navgrid.json")
    .navgrid("backoff","backoff_navgrid.json"));
PumpkinNav.useProfile("auto");
Command c = PumpkinNav.to(Poses.REEF_A, PumpkinConstraints.of(3.0, 4.0, Degrees.of(540), Degrees.of(720)));
Command d = PumpkinNav.toThenFollow(PathPlannerPath.fromPathFile("Score"), constraints);

PumpkinDrive drive = PumpkinDrive.phoenix6(swerveDrivetrain)
    .withWheelForceFeedforwards(true)
    .withSetpointGenerator(new SwerveSetpointGenerator(robotConfig, RotationsPerSecond.of(10)))
    .withDiscretization(0.02);
// PumpkinDrive implements both the PathPlanner output BiConsumer<ChassisSpeeds,DriveFeedforwards>
// and the Choreo Consumer<SwerveSample>, so AutoBuilder.configure(...) and
// new AutoFactory(..., drive::followSample, ...) both take the same object.
drive.accept(sample);           // SwerveSample: uses sample.moduleForcesX()/moduleForcesY()
drive.accept(speeds, ff);       // DriveFeedforwards: robotRelativeForcesXNewtons()/Y

PumpkinField.configure(FieldSymmetry.ROTATIONAL);   // or MIRRORED, per game year
PumpkinAuto.allianceFlip(() -> DriverStation.getAlliance().orElse(Alliance.Blue) == Alliance.Red);
// Then everywhere: poses authored on BLUE only.
Pose2d p = PumpkinField.apply(Poses.REEF_A);          // alliance-corrected
PumpkinTrajectory t = auto.choreo("startToScore");    // flips automatically
PumpkinTrajectory left  = auto.choreo("sweep");
PumpkinTrajectory right = left.mirroredAboutMidline(); // driver-perspective left/right variant
// Startup assertion: PumpkinField.verify() logs the transformed start pose of every registered
// auto for both alliances so you can eyeball them in AdvantageScope before an event.

PumpkinAutoLogging.attach(logger);   // wires:
//   PathPlannerLogging.setLogActivePathCallback / setLogTargetPoseCallback / setLogCurrentPoseCallback
